INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (0.0, 0.0, 0.0, 24, 1, 10021, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24015, 4, 4, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (4.0, 0.0, 0.0, 24, 2, 10021, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24016, 1, 4, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (0.0, 0.0, 0.0, 24, 3, 10021, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24017, 4, 4, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (5.2, 0.0, 0.0, 24, 4, 10021, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24018, 2, 1, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (4.2, 0.0, 0.0, 24, 5, 10021, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24019, 6, 5, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (0.0, 0.0, 0.0, 24, 6, 10021, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24020, 2, 2, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (6.4, 0.0, 0.0, 24, 7, 10021, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24021, 6, 1, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (0.0, 0.0, 0.0, 24, 8, 10021, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24022, 2, 2, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (10.08, 0.0, 0.0, 24, 9, 10021, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24023, 3, 6, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (5.0, 0.0, 0.0, 24, 10, 10021, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24024, 2, 1, "2019/07/31 12:00:00");
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES (0.0, 0.0, 0.0, 24, 11, 10021, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 110501, "カオリ（サマー）", "2030/12/17 14:59:59", 24025, 2, 2, "2019/07/31 12:00:00");
